"""Throughput models: FLOPs and bytes moved per op, as a function of the
case parameters.

These are the roofline denominators (see the project wiki's roofline
method): FLOP/s against the compute roof, bytes/s against the HBM roof.
Models assume float32 (4 bytes/element) and beta=0 GEMMs (C written once).
"""

from __future__ import annotations

from typing import Callable

__all__ = ["model_for", "register_throughput_model", "ThroughputModel"]

#: op -> callable(params dict) -> (flops, bytes)
_MODELS: dict[str, Callable[[dict], tuple[int, int]]] = {}


def ThroughputModel(op: str):  # noqa: N802 — decorator, named like the concept
    """Register a throughput model: ``@ThroughputModel("gemm")``."""

    def decorate(fn: Callable[[dict], tuple[int, int]]) -> Callable[[dict], tuple[int, int]]:
        _MODELS[op] = fn
        return fn

    return decorate


def register_throughput_model(op: str, fn: Callable[[dict], tuple[int, int]]) -> None:
    """Imperative form of :func:`ThroughputModel`."""
    _MODELS[op] = fn


def _elementwise(rw_arrays: int) -> Callable[[dict], tuple[int, int]]:
    def model(params: dict) -> tuple[int, int]:
        n = params["size"]
        return n, rw_arrays * n * 4

    return model


@ThroughputModel("add")
def _add(params: dict) -> tuple[int, int]:
    return _elementwise(3)(params)


@ThroughputModel("scale")
def _scale(params: dict) -> tuple[int, int]:
    return _elementwise(2)(params)


@ThroughputModel("relu")
def _relu(params: dict) -> tuple[int, int]:
    return _elementwise(2)(params)


@ThroughputModel("sum")
def _sum(params: dict) -> tuple[int, int]:
    n = params["size"]
    return n, n * 4 + 4  # read n, write one scalar


@ThroughputModel("max")
def _max(params: dict) -> tuple[int, int]:
    n = params["size"]
    return n, n * 4 + 4


@ThroughputModel("gemm")
def _gemm(params: dict) -> tuple[int, int]:
    m = params["size"]
    n = params.get("n", 16)
    k = params.get("k", 16)
    flops = 2 * m * n * k
    bytes_ = (m * k + k * n + 2 * m * n) * 4  # A read, B read, C write
    return flops, bytes_


def model_for(op: str, params: dict) -> tuple[int, int]:
    """``(flops, bytes)`` for one case of ``op`` at these parameters."""
    try:
        model = _MODELS[op]
    except KeyError:
        raise KeyError(
            f"no throughput model for {op!r}; available: {', '.join(sorted(_MODELS))}"
        ) from None
    return model(dict(params))

"""Compare two benchmark JSON reports (the PR CI flow).

The flow (borrowed from tokenspeed-kernel's PR benchmark comparison):
run the suite on the merge base, run it on the candidate, compare — a case
whose median runtime regressed beyond the threshold fails the check; new
and removed cases are reported but do not fail it (a new case has no
baseline; a removed one cannot regress).
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal

__all__ = ["ComparisonRow", "ComparisonReport", "compare"]

Verdict = Literal["ok", "regression", "improved", "new", "missing", "error"]


@dataclass(frozen=True)
class ComparisonRow:
    key: str
    verdict: Verdict
    baseline_ms: float | None = None
    current_ms: float | None = None
    ratio: float | None = None  # current / baseline
    detail: str = ""


@dataclass(frozen=True)
class ComparisonReport:
    threshold: float
    rows: tuple[ComparisonRow, ...]

    @property
    def regressions(self) -> tuple[ComparisonRow, ...]:
        return tuple(r for r in self.rows if r.verdict == "regression")

    @property
    def ok(self) -> bool:
        return not self.regressions

    def __str__(self) -> str:
        lines = [f"benchmark comparison (threshold {self.threshold:.0%})"]
        for row in self.rows:
            base = f"{row.baseline_ms:.3f}" if row.baseline_ms else "-"
            cur = f"{row.current_ms:.3f}" if row.current_ms else "-"
            ratio = f"{row.ratio:.2f}x" if row.ratio else ""
            lines.append(f"  {row.verdict:<10} {row.key}: {base} -> {cur} ms {ratio}")
        summary = (
            f"{len(self.rows)} cases, {len(self.regressions)} regression(s)"
            if self.rows
            else "no comparable cases"
        )
        lines.append(summary)
        return "\n".join(lines)


def compare(baseline: dict, current: dict, *, threshold: float = 0.10) -> ComparisonReport:
    """Compare two :func:`~vkernels.benchmark.report.to_json` documents."""
    if baseline.get("schema") != current.get("schema"):
        raise ValueError("schema mismatch between baseline and current")
    base_rows = {row["key"]: row for row in baseline.get("results", [])}
    cur_rows = {row["key"]: row for row in current.get("results", [])}

    rows: list[ComparisonRow] = []
    for key in sorted(base_rows.keys() | cur_rows.keys()):
        base, cur = base_rows.get(key), cur_rows.get(key)
        if base is None:
            rows.append(ComparisonRow(key, "new", current_ms=_ms(cur)))
            continue
        if cur is None:
            rows.append(ComparisonRow(key, "missing", baseline_ms=_ms(base)))
            continue
        if cur.get("error"):
            rows.append(
                ComparisonRow(key, "error", _ms(base), _ms(cur), detail=cur["error"])
            )
            continue
        base_ms, cur_ms = _ms(base), _ms(cur)
        if base_ms is None or cur_ms is None or base_ms <= 0 or cur_ms <= 0:
            rows.append(ComparisonRow(key, "error", base_ms, cur_ms, detail="invalid timing"))
            continue
        ratio = cur_ms / base_ms
        if ratio > 1 + threshold:
            verdict: Verdict = "regression"
        elif ratio < 1 - threshold:
            verdict = "improved"
        else:
            verdict = "ok"
        rows.append(ComparisonRow(key, verdict, base_ms, cur_ms, ratio))
    return ComparisonReport(threshold, tuple(rows))


def _ms(row: dict | None) -> float | None:
    if row is None:
        return None
    seconds = row.get("seconds")
    return seconds * 1e3 if isinstance(seconds, (int, float)) else None

