// vkernels/kernels/common/epilogue.hpp — composable GEMM epilogue operators.
//
// The store-side math of ``D = C + A @ B`` expressed as small structs that
// both the CPU oracle (gemm.cpp) and the CUDA kernels (gemm.cu and friends)
// instantiate, so a fused epilogue is one type, not a copy of the kernel
// with the last line edited. Layout borrowed from DeepGEMM's
// ``include/deep_gemm/epilogue/operators.cuh`` layering, scaled down to
// this repo's two-implementation model.
//
// Every epilogue is ``float apply(float acc, float c_prev) const``:
// ``acc`` is the K-loop accumulator, ``c_prev`` the existing output
// element (valid only when the epilogue reads it — see Linear's beta rule).
// Host- and device-usable: no CUDA headers, no exceptions.
#pragma once

namespace vkernels::kernels::epilogue {

// C = alpha * acc + beta * C_prev, with BLAS beta semantics: beta == 0
// must not read C_prev (0 * NaN would poison the store; this is the rule
// the CUDA gemm always honored and the CPU oracle now shares).
struct Linear {
  float alpha;
  float beta;

  constexpr float apply(float acc, float c_prev) const {
    const float prev = (beta != 0.0f) ? c_prev : 0.0f;
    return alpha * acc + beta * prev;
  }
};

// relu(base(...)). Matches the standalone relu kernel's fmaxf semantics:
// a non-positive value (including NaN from the base) maps to 0.
template <typename Base>
struct Relu {
  Base base;

  constexpr float apply(float acc, float c_prev) const {
    const float v = base.apply(acc, c_prev);
    return (v > 0.0f) ? v : 0.0f;
  }
};

using LinearRelu = Relu<Linear>;

}  // namespace vkernels::kernels::epilogue

// vkernels/kernels/common/launch.hpp — the CUDA launch-and-check idiom.
//
// Every device launcher in this tree ended with the same three lines:
// ``kernel<<<grid, block>>>(args...)`` then ``cudaGetLastError`` funneled
// into VK_ENSURES with a hand-written message. :func:`vkernels::kernels::common::launch`
// keeps the idiom in one place (the ``common/`` layering borrowed from
// DeepGEMM's include tree), so a launcher is one call and a missing check
// is impossible by construction.
//
// CUDA-only content: include from translation units compiled with a
// toolkit (the .cu files guard themselves with VKERNELS_HAS_CUDA the same
// way).
#pragma once

#include <cstddef>

#if VKERNELS_HAS_CUDA

#  include <cuda_runtime.h>

#  include <string>

#  include "vkernels/util/error.hpp"

namespace vkernels::kernels::common {

inline std::size_t ceil_div(std::size_t value, std::size_t divisor) {
  return (value + divisor - 1) / divisor;
}

// Threads-per-block for a flat 1-D elementwise-style kernel.
inline int default_block_size() { return 256; }

// Launch ``kernel`` with ``args...`` and fail through VK_ENSURES on any
// launch error. ``what`` names the operation in the error message.
template <typename... Args>
void launch(void (*kernel)(Args...), dim3 grid, dim3 block, const char* what,
            Args... args) {
  kernel<<<grid, block>>>(args...);
  cudaError_t err = cudaGetLastError();
  VK_ENSURES(err == cudaSuccess, std::string(what) + " launch failed");
}

// 1-D convenience: grid sized for ``n`` elements at ``threads`` per block.
template <typename... Args>
void launch_1d(void (*kernel)(Args...), std::size_t n, const char* what,
               Args... args) {
  const int threads = default_block_size();
  const dim3 grid(static_cast<unsigned>(ceil_div(n, static_cast<std::size_t>(threads))));
  launch(kernel, grid, dim3(static_cast<unsigned>(threads)), what, args...);
}

}  // namespace vkernels::kernels::common

#endif  // VKERNELS_HAS_CUDA

// vkernels/kernels/common/heuristics.hpp — launch-config candidates as data.
//
// The per-arch config selectors (gemm_bf16_config_for and friends) encode
// *decisions*; this header holds the *search space* they decide over: the
// tile tables the on-device autotuners swept (bench_gemm_bf16 /
// bench_gemm_bf16.hip, persisted through docs/tuning-cache.md's store).
// Keeping the enumeration next to the selector — the layering DeepGEMM
// uses for csrc/jit_kernels/heuristics — means a new shape class sweeps
// the same table instead of growing a one-off branch.
#pragma once

#include <vector>

#include "vkernels/util/config.hpp"

namespace vkernels::kernels::heuristics {

// One candidate GEMM tile: block M/N/K plus the threads (CUDA) or
// wavefronts (HIP) the kernel runs it at.
struct GemmTile {
  int bm;
  int bn;
  int bk;
  int threads;
};

// The tile set the gemm_bf16 autotuners swept. BK is 64 everywhere (every
// K3 K is a multiple of 64). Ordered small-to-large; selectors return
// entries from this table so the tuned decision and the sweep space stay
// in sync.
//
// CUDA (GB10 / sm_121): (16,16)@32, (16,64)@128, (64,64)@256 — the three
//   points the cp.async double-buffered kernel's matrices in
//   docs/performance/gemm-bf16/gb10.md were regenerated against.
// HIP (MI300A / gfx942): (16,16)@64 and (64,64)@256 — the flat tiles the
//   228-CU autotuner kept (the cross-tile B-reuse schedule lost ~2x and
//   lives behind gemm_bf16_reuse_with_config for offline experiments).
inline std::vector<GemmTile> gemm_bf16_tile_candidates() {
#if VKERNELS_HAS_CUDA
  return {
      {16, 16, 64, 32}, {16, 64, 64, 128}, {64, 64, 64, 256},
  };
#else
  return {
      {16, 16, 64, 64},
      {64, 64, 64, 256},
  };
#endif
}

// Whether (bm, bn, bk, threads) is one of the swept candidates — the
// contract the config selectors must satisfy (a returned tile outside the
// table was never measured).
inline bool is_gemm_bf16_candidate(int bm, int bn, int bk, int threads) {
  for (const GemmTile& tile : gemm_bf16_tile_candidates()) {
    if (tile.bm == bm && tile.bn == bn && tile.bk == bk && tile.threads == threads) {
      return true;
    }
  }
  return false;
}

}  // namespace vkernels::kernels::heuristics

