// vkernels/kernels/mqa_logits.hpp — weighted ReLU MQA logits (lightning
// indexer scoring), borrowed from DeepGEMM's kernel family
// (fp8_fp4_mqa_logits / fp8_fp4_paged_mqa_logits, MIT (c) 2025 DeepSeek).
//
// For every query row m with per-row KV span [cu_seq_len_k_start[m],
// cu_seq_len_k_end[m]) over the shared single-head KV cache:
//
//     out[m, n] = sum_h weights[m, h] * relu( sum_d q[m, h, d] * kv[n, d] )
//
// and -inf outside the row's span. (DeepGEMM additionally compresses the
// output to [M, max_seqlen_k] packing each row's span at column zero; this
// tree keeps the dense [M, N] layout — the compression is a serving-side
// layout concern owned by the caller.)
//
// Layouts (row-major): q [M, H, D], kv [N, D], weights [M, H], cu_* [M]
// (int), out [M, N].
#pragma once

#include <cstddef>

#include "vkernels/util/span.hpp"

namespace vkernels::kernels {

void mqa_logits(std::size_t M, std::size_t N, std::size_t H, std::size_t D,
                Span<const float> q, Span<const float> kv,
                Span<const float> weights,
                Span<const int> cu_seq_len_k_start,
                Span<const int> cu_seq_len_k_end, Span<float> out);

namespace cuda {
// Device-pointer variant; same contract as the CPU oracle above.
void mqa_logits(std::size_t M, std::size_t N, std::size_t H, std::size_t D,
                Span<const float> q, Span<const float> kv,
                Span<const float> weights,
                Span<const int> cu_seq_len_k_start,
                Span<const int> cu_seq_len_k_end, Span<float> out);
}  // namespace cuda
}  // namespace vkernels::kernels

// vkernels/kernels/gemm_grouped.hpp — masked m-grouped GEMM for
// CUDA-graph MoE decode, borrowed from DeepGEMM's
// m_grouped_fp8_gemm_nt_masked contract (MIT (c) 2025 DeepSeek).
//
// Groups share the M/N/K problem shape; a device-resident ``masked_m``
// gives the valid row count per group, so a graph captured without knowing
// per-expert token counts still computes exactly the live rows:
//
//     C[g, m, n] = sum_k A[g, m, k] * B[g, n, k]        (NT: B used transposed)
//
// for m < masked_m[g]; rows at or beyond masked_m[g] are LEFT UNTOUCHED —
// callers pre-poison them (NaN) to detect leakage. Layouts (row-major):
// A [G, M, K], B [G, N, K], masked_m [G] (int), C [G, M, N].
#pragma once

#include <cstddef>

#include "vkernels/util/span.hpp"

namespace vkernels::kernels {

void m_grouped_gemm_nt_masked(std::size_t G, std::size_t M, std::size_t N,
                              std::size_t K, Span<const float> A,
                              Span<const float> B, Span<const int> masked_m,
                              Span<float> C);

namespace cuda {
// Device-pointer variant; same contract as the CPU oracle above.
void m_grouped_gemm_nt_masked(std::size_t G, std::size_t M, std::size_t N,
                              std::size_t K, Span<const float> A,
                              Span<const float> B, Span<const int> masked_m,
                              Span<float> C);
}  // namespace cuda
}  // namespace vkernels::kernels

// vkernels/kernels/mqa_logits.cpp — CPU reference (oracle) implementation.
#include "vkernels/kernels/mqa_logits.hpp"

#include <limits>

#include "vkernels/util/error.hpp"

namespace vkernels::kernels {

void mqa_logits(std::size_t M, std::size_t N, std::size_t H, std::size_t D,
                Span<const float> q, Span<const float> kv,
                Span<const float> weights, Span<const int> cu_seq_len_k_start,
                Span<const int> cu_seq_len_k_end, Span<float> out) {
  VK_EXPECTS(q.size() == M * H * D, "q must be M*H*D");
  VK_EXPECTS(kv.size() == N * D, "kv must be N*D");
  VK_EXPECTS(weights.size() == M * H, "weights must be M*H");
  VK_EXPECTS(cu_seq_len_k_start.size() == M, "cu_seq_len_k_start must be M");
  VK_EXPECTS(cu_seq_len_k_end.size() == M, "cu_seq_len_k_end must be M");
  VK_EXPECTS(out.size() == M * N, "out must be M*N");

  const float neg_inf = -std::numeric_limits<float>::infinity();
  for (std::size_t m = 0; m < M; ++m) {
    const int k_start = cu_seq_len_k_start[m];
    const int k_end = cu_seq_len_k_end[m];
    VK_EXPECTS(k_start >= 0 && static_cast<std::size_t>(k_start) <= N,
               "cu_seq_len_k_start must be within [0, N]");
    VK_EXPECTS(k_end >= k_start && static_cast<std::size_t>(k_end) <= N,
               "cu_seq_len_k_end must be within [start, N]");
    for (std::size_t n = 0; n < N; ++n) {
      float acc = 0.0f;
      if (static_cast<int>(n) >= k_start && static_cast<int>(n) < k_end) {
        for (std::size_t h = 0; h < H; ++h) {
          float dot = 0.0f;
          for (std::size_t d = 0; d < D; ++d) {
            dot += q[(m * H + h) * D + d] * kv[n * D + d];
          }
          if (dot > 0.0f) acc += weights[m * H + h] * dot;
        }
      } else {
        acc = neg_inf;
      }
      out[m * N + n] = acc;
    }
  }
}

}  // namespace vkernels::kernels

// vkernels/kernels/gemm_grouped.cpp — CPU reference (oracle) implementation.
#include "vkernels/kernels/gemm_grouped.hpp"

#include "vkernels/util/error.hpp"

namespace vkernels::kernels {

void m_grouped_gemm_nt_masked(std::size_t G, std::size_t M, std::size_t N,
                              std::size_t K, Span<const float> A,
                              Span<const float> B, Span<const int> masked_m,
                              Span<float> C) {
  VK_EXPECTS(A.size() == G * M * K, "A must be G*M*K");
  VK_EXPECTS(B.size() == G * N * K, "B must be G*N*K");
  VK_EXPECTS(masked_m.size() == G, "masked_m must be G");
  VK_EXPECTS(C.size() == G * M * N, "C must be G*M*N");

  for (std::size_t g = 0; g < G; ++g) {
    const int valid = masked_m[g];
    VK_EXPECTS(valid >= 0 && static_cast<std::size_t>(valid) <= M,
               "masked_m must be within [0, M]");
    for (std::size_t m = 0; m < static_cast<std::size_t>(valid); ++m) {
      for (std::size_t n = 0; n < N; ++n) {
        float acc = 0.0f;
        for (std::size_t k = 0; k < K; ++k) {
          acc += A[(g * M + m) * K + k] * B[(g * N + n) * K + k];
        }
        C[(g * M + m) * N + n] = acc;
      }
    }
    // Rows at or beyond masked_m[g] stay untouched (graph-decode contract).
  }
}

}  // namespace vkernels::kernels

// vkernels/kernels/mqa_logits.cu — CUDA implementation (compiled with a
// toolkit). Kernel design borrowed from DeepGEMM's sm90_fp8_mqa_logits
// family: one program per (query row, KV tile), the weighted-ReLU MQA
// scoring loop over the row's span. This first cut keeps the mapping
// simple (one thread per output element) — the oracle-parity contract is
// the deliverable; the tuned tile ladder lands with profiling.
#include "vkernels/kernels/mqa_logits.hpp"

#if VKERNELS_HAS_CUDA
#  include <cuda_runtime.h>

#  include <limits>

#  include "vkernels/kernels/common/launch.hpp"
#  include "vkernels/util/error.hpp"

namespace vkernels::kernels {

namespace {

__global__ void mqa_logits_kernel(const float* __restrict__ q,
                                  const float* __restrict__ kv,
                                  const float* __restrict__ weights,
                                  const int* __restrict__ cu_ks,
                                  const int* __restrict__ cu_ke,
                                  float* __restrict__ out, int M, int N, int H,
                                  int D) {
  const int m = blockIdx.y;
  const int n = blockIdx.x * blockDim.x + threadIdx.x;
  if (m >= M || n >= N) return;
  const float neg_inf = -std::numeric_limits<float>::infinity();
  if (n < cu_ks[m] || n >= cu_ke[m]) {
    out[m * N + n] = neg_inf;
    return;
  }
  float acc = 0.0f;
  for (int h = 0; h < H; ++h) {
    float dot = 0.0f;
    const float* q_row = q + (static_cast<std::size_t>(m) * H + h) * D;
    const float* k_row = kv + static_cast<std::size_t>(n) * D;
    for (int d = 0; d < D; ++d) dot += q_row[d] * k_row[d];
    if (dot > 0.0f) acc += weights[m * H + h] * dot;
  }
  out[m * N + n] = acc;
}

}  // namespace

namespace cuda {

void mqa_logits(std::size_t M, std::size_t N, std::size_t H, std::size_t D,
                Span<const float> q, Span<const float> kv,
                Span<const float> weights, Span<const int> cu_seq_len_k_start,
                Span<const int> cu_seq_len_k_end, Span<float> out) {
  VK_EXPECTS(q.size() == M * H * D, "q must be M*H*D");
  VK_EXPECTS(kv.size() == N * D, "kv must be N*D");
  VK_EXPECTS(weights.size() == M * H, "weights must be M*H");
  VK_EXPECTS(cu_seq_len_k_start.size() == M, "cu_seq_len_k_start must be M");
  VK_EXPECTS(cu_seq_len_k_end.size() == M, "cu_seq_len_k_end must be M");
  VK_EXPECTS(out.size() == M * N, "out must be M*N");
  if (M == 0 || N == 0) return;

  const int threads = static_cast<int>(common::default_block_size());
  const dim3 grid(static_cast<unsigned>(common::ceil_div(N, static_cast<std::size_t>(threads))),
                  static_cast<unsigned>(M));
  common::launch(mqa_logits_kernel, grid, dim3(static_cast<unsigned>(threads)),
                 "cuda mqa_logits", q.data(), kv.data(), weights.data(),
                 cu_seq_len_k_start.data(), cu_seq_len_k_end.data(), out.data(),
                 static_cast<int>(M), static_cast<int>(N), static_cast<int>(H),
                 static_cast<int>(D));
}

}  // namespace cuda
}  // namespace vkernels::kernels

#endif  // VKERNELS_HAS_CUDA

// vkernels/kernels/gemm_grouped.cu — CUDA implementation (compiled with a
// toolkit). Masked m-grouped GEMM for CUDA-graph MoE decode, borrowed
// from DeepGEMM's m_grouped_*_gemm_nt_masked contract: the per-group
// valid row count lives in device memory, so a captured graph computes
// exactly the live rows and leaves masked rows untouched. First cut maps
// one thread per output element (oracle parity is the deliverable; the
// tile/pipeline ladder lands with profiling).
#include "vkernels/kernels/gemm_grouped.hpp"

#if VKERNELS_HAS_CUDA
#  include <cuda_runtime.h>

#  include "vkernels/kernels/common/launch.hpp"
#  include "vkernels/util/error.hpp"

namespace vkernels::kernels {

namespace {

__global__ void m_grouped_gemm_nt_masked_kernel(const float* __restrict__ A,
                                                const float* __restrict__ B,
                                                const int* __restrict__ masked_m,
                                                float* __restrict__ C, int G, int M,
                                                int N, int K) {
  const std::size_t linear =
      static_cast<std::size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
  const std::size_t total = static_cast<std::size_t>(G) * M * N;
  if (linear >= total) return;
  const std::size_t n = linear % N;
  const std::size_t m = (linear / N) % M;
  const std::size_t g = linear / (static_cast<std::size_t>(M) * N);
  if (m >= static_cast<std::size_t>(masked_m[g])) return;  // row stays untouched

  const float* a = A + (g * M + m) * K;
  const float* b = B + (g * N + n) * K;
  float acc = 0.0f;
  for (std::size_t k = 0; k < K; ++k) acc += a[k] * b[k];
  C[linear] = acc;
}

}  // namespace

namespace cuda {

void m_grouped_gemm_nt_masked(std::size_t G, std::size_t M, std::size_t N,
                              std::size_t K, Span<const float> A,
                              Span<const float> B, Span<const int> masked_m,
                              Span<float> C) {
  VK_EXPECTS(A.size() == G * M * K, "A must be G*M*K");
  VK_EXPECTS(B.size() == G * N * K, "B must be G*N*K");
  VK_EXPECTS(masked_m.size() == G, "masked_m must be G");
  VK_EXPECTS(C.size() == G * M * N, "C must be G*M*N");
  const std::size_t total = G * M * N;
  if (total == 0) return;

  const int threads = static_cast<int>(common::default_block_size());
  const dim3 grid(static_cast<unsigned>(common::ceil_div(total, static_cast<std::size_t>(threads))));
  common::launch(m_grouped_gemm_nt_masked_kernel, grid,
                 dim3(static_cast<unsigned>(threads)), "cuda m_grouped_gemm_nt_masked",
                 A.data(), B.data(), masked_m.data(), C.data(),
                 static_cast<int>(G), static_cast<int>(M), static_cast<int>(N),
                 static_cast<int>(K));
}

}  // namespace cuda
}  // namespace vkernels::kernels

#endif  // VKERNELS_HAS_CUDA

// tests/kernels/indexer/test_indexer_grouped.cpp — oracle contracts for the
// DeepGEMM-borrowed kernels: weighted-ReLU MQA logits (lightning indexer
// scoring) and the masked m-grouped GEMM (CUDA-graph MoE decode). Device
// parity runs in test_cuda_contracts.cu on toolkit builds.
#include "vkernels/kernels/gemm_grouped.hpp"
#include "vkernels/kernels/mqa_logits.hpp"

#include <cmath>
#include <limits>
#include <vector>

#include "minitest.hpp"

namespace {

std::vector<float> mk(std::size_t n, float value) { return std::vector<float>(n, value); }

}  // namespace

TEST(MqaLogits, WeightedReluOverSpan) {
  // 2 query rows, 3 KV tokens, 2 heads, head dim 2.
  const std::size_t M = 2, N = 3, H = 2, D = 2;
  std::vector<float> q{
      1, 0, 0, 1,   // m0: h0 = (1,0), h1 = (0,1)
      2, 0, 0, -2,  // m1: h0 = (2,0), h1 = (0,-2)
  };
  std::vector<float> kv{
      1, 2,   // n0
      -1, 3,  // n1
      4, 0,   // n2
  };
  std::vector<float> weights{
      0.5f, 2.0f,  // m0
      1.0f, 3.0f,  // m1
  };
  std::vector<int> ks{0, 1};
  std::vector<int> ke{2, 3};  // m0 sees n0..n1; m1 sees n1..n2
  std::vector<float> out(M * N, 0.0f);

  vkernels::kernels::mqa_logits(M, N, H, D, q, kv, weights, ks, ke, out);

  const float neg_inf = -std::numeric_limits<float>::infinity();
  // m0, n0: relu(1)=1*0.5 + relu(2)=2*2 => 4.5
  EXPECT_NEAR(out[0], 4.5f, 1e-6);
  // m0, n1: relu(-1)=0 + relu(3)=3*2 => 6
  EXPECT_NEAR(out[1], 6.0f, 1e-6);
  // m0, n2: outside span
  EXPECT_TRUE(std::isinf(out[2]) && out[2] < 0);
  // m1, n0: outside span
  EXPECT_TRUE(std::isinf(out[3]) && out[3] < 0);
  // m1, n1: relu(-1)=0*1 + relu(3)=3*3 => 9  (h1 = (0,-2) . (-1,3) = -6 -> 0)
  EXPECT_NEAR(out[4], 9.0f, 1e-6);
  // m1, n2: relu(8)=8*1 + relu(0)=0 => 8
  EXPECT_NEAR(out[5], 8.0f, 1e-6);
}

TEST(MqaLogits, NegativeReluSuppresses) {
  const std::size_t M = 1, N = 1, H = 1, D = 1;
  std::vector<float> q{-3.0f}, kv{5.0f}, weights{7.0f};
  std::vector<int> ks{0}, ke{1};
  std::vector<float> out(1, 99.0f);
  vkernels::kernels::mqa_logits(M, N, H, D, q, kv, weights, ks, ke, out);
  EXPECT_NEAR(out[0], 0.0f, 1e-6);  // relu(-15) = 0, weight irrelevant
}

TEST(MqaLogits, EmptySpanIsAllMasked) {
  const std::size_t M = 1, N = 4, H = 1, D = 1;
  std::vector<float> q{1}, kv(4, 1.0f), weights{1};
  std::vector<int> ks{2}, ke{2};  // empty span
  std::vector<float> out(M * N, 0.0f);
  vkernels::kernels::mqa_logits(M, N, H, D, q, kv, weights, ks, ke, out);
  for (float v : out) EXPECT_TRUE(std::isinf(v) && v < 0);
}

TEST(MqaLogits, ShapeValidation) {
  std::vector<float> q(4), kv(4), weights(4), out(4);
  std::vector<int> ks(2), ke(2);
  EXPECT_THROW(vkernels::kernels::mqa_logits(2, 2, 2, 2, q, kv, mk(3, 0), ks, ke, out),
               std::invalid_argument);
  std::vector<int> bad_ke{0, 3};  // end beyond N=2
  EXPECT_THROW(vkernels::kernels::mqa_logits(2, 2, 1, 2, q, kv, mk(2, 0), ks, bad_ke, out),
               std::invalid_argument);
}

TEST(GroupedGemmMasked, ComputesValidRowsOnlyAndLeavesMaskedUntouched) {
  const std::size_t G = 2, M = 3, N = 2, K = 2;
  // A[g] rows: all 1s (row m of group g = m+g pattern via fill below).
  std::vector<float> A(G * M * K), B(G * N * K), C(G * M * N);
  for (std::size_t g = 0; g < G; ++g)
    for (std::size_t m = 0; m < M; ++m)
      for (std::size_t k = 0; k < K; ++k) A[(g * M + m) * K + k] = float(m + 1);
  for (std::size_t g = 0; g < G; ++g)
    for (std::size_t n = 0; n < N; ++n)
      for (std::size_t k = 0; k < K; ++k) B[(g * N + n) * K + k] = float(g + 1);
  const float poison = std::numeric_limits<float>::quiet_NaN();
  for (float& c : C) c = poison;
  std::vector<int> masked{2, 0};  // group 0: rows 0-1; group 1: none

  vkernels::kernels::m_grouped_gemm_nt_masked(G, M, N, K, A, B, masked, C);

  for (std::size_t m = 0; m < M; ++m) {
    for (std::size_t n = 0; n < N; ++n) {
      const float c0 = C[(0 * M + m) * N + n];
      const float c1 = C[(1 * M + m) * N + n];
      if (m < 2) {
        // group 0: (m+1) * (1 + 1) summed over K=2
        EXPECT_NEAR(c0, 2.0f * (m + 1), 1e-6);
      } else {
        EXPECT_TRUE(std::isnan(c0));  // masked row untouched
      }
      EXPECT_TRUE(std::isnan(c1));  // group 1 fully masked
    }
  }
}

TEST(GroupedGemmMasked, NTUsesBTransposed) {
  const std::size_t G = 1, M = 1, N = 2, K = 3;
  std::vector<float> A{1, 2, 3};
  std::vector<float> B{1, 0, 0, 0, 1, 0};  // B[0]=(1,0,0), B[1]=(0,1,0)
  std::vector<float> C(2, 0.0f);
  std::vector<int> masked{1};
  vkernels::kernels::m_grouped_gemm_nt_masked(G, M, N, K, A, B, masked, C);
  EXPECT_NEAR(C[0], 1.0f, 1e-6);  // A . B[0]
  EXPECT_NEAR(C[1], 2.0f, 1e-6);  // A . B[1]
}

TEST(GroupedGemmMasked, ShapeValidation) {
  std::vector<float> A(8), B(8), C(8);
  std::vector<int> masked{1, 5};  // 5 > M=2
  EXPECT_THROW(vkernels::kernels::m_grouped_gemm_nt_masked(2, 2, 2, 2, A, B, masked, C),
               std::invalid_argument);
}

// tests/kernels/indexer/test_indexer_grouped_cuda.cu — device parity for
// the DeepGEMM-borrowed kernels: cuda::mqa_logits and
// cuda::m_grouped_gemm_nt_masked against their CPU oracles on this device.
#include "minitest.hpp"
#include <cuda_runtime.h>
#include <cmath>
#include <limits>
#include <vector>

#include "vkernels/kernels/gemm_grouped.hpp"
#include "vkernels/kernels/mqa_logits.hpp"

namespace {

struct FBuf {
  float* ptr = nullptr;
  explicit FBuf(std::size_t n) { EXPECT_EQ(cudaMalloc(&ptr, n * sizeof(float)), cudaSuccess); }
  ~FBuf() { cudaFree(ptr); }
};

struct IBuf {
  int* ptr = nullptr;
  explicit IBuf(std::size_t n) { EXPECT_EQ(cudaMalloc(&ptr, n * sizeof(int)), cudaSuccess); }
  ~IBuf() { cudaFree(ptr); }
};

void expect_same(const std::vector<float>& got, const std::vector<float>& want, float tol) {
  EXPECT_EQ(got.size(), want.size());
  for (std::size_t i = 0; i < got.size(); ++i) {
    if (std::isinf(want[i])) {
      EXPECT_TRUE(std::isinf(got[i]) && got[i] < 0);
    } else {
      EXPECT_NEAR(got[i], want[i], tol);
    }
  }
}

}  // namespace

TEST(IndexerGroupedCuda, MqaLogitsMatchesOracle) {
  const std::size_t M = 5, N = 37, H = 3, D = 8;
  std::vector<float> q(M * H * D), kv(N * D), weights(M * H);
  std::vector<int> ks(M), ke(M);
  unsigned seed = 12345;
  auto rnd = [&seed]() {
    seed = seed * 1103515245u + 12345u;
    return static_cast<float>(static_cast<int>(seed >> 16 & 0x7fff) % 200 - 100) / 10.0f;
  };
  for (float& v : q) v = rnd();
  for (float& v : kv) v = rnd();
  for (float& v : weights) v = rnd();
  for (std::size_t m = 0; m < M; ++m) {
    ks[m] = static_cast<int>(m % 7);
    ke[m] = static_cast<int>(N - (m % 11));
  }

  std::vector<float> oracle(M * N), device(M * N);
  vkernels::kernels::mqa_logits(M, N, H, D, q, kv, weights, ks, ke, oracle);

  FBuf dq(q.size()), dkv(kv.size()), dw(weights.size()), dout(device.size());
  IBuf dks(ks.size()), dke(ke.size());
  cudaMemcpy(dq.ptr, q.data(), q.size() * sizeof(float), cudaMemcpyHostToDevice);
  cudaMemcpy(dkv.ptr, kv.data(), kv.size() * sizeof(float), cudaMemcpyHostToDevice);
  cudaMemcpy(dw.ptr, weights.data(), weights.size() * sizeof(float), cudaMemcpyHostToDevice);
  cudaMemcpy(dks.ptr, ks.data(), ks.size() * sizeof(int), cudaMemcpyHostToDevice);
  cudaMemcpy(dke.ptr, ke.data(), ke.size() * sizeof(int), cudaMemcpyHostToDevice);
  vkernels::kernels::cuda::mqa_logits(M, N, H, D, {dq.ptr, q.size()}, {dkv.ptr, kv.size()},
                                      {dw.ptr, weights.size()}, {dks.ptr, ks.size()},
                                      {dke.ptr, ke.size()}, {dout.ptr, device.size()});
  EXPECT_EQ(cudaMemcpy(device.data(), dout.ptr, device.size() * sizeof(float),
                        cudaMemcpyDeviceToHost),
            cudaSuccess);
  expect_same(device, oracle, 1e-4);
}

TEST(IndexerGroupedCuda, MaskedGroupedGemmMatchesOracleAndKeepsMaskedRows) {
  const std::size_t G = 3, M = 9, N = 7, K = 16;
  std::vector<float> A(G * M * K), B(G * N * K), C(G * M * N, 0.0f);
  std::vector<int> masked{4, 0, 9};
  unsigned seed = 999;
  auto rnd = [&seed]() {
    seed = seed * 1103515245u + 12345u;
    return static_cast<float>(static_cast<int>(seed >> 16 & 0x7fff) % 50 - 25) / 5.0f;
  };
  for (float& v : A) v = rnd();
  for (float& v : B) v = rnd();

  std::vector<float> oracle(G * M * N, 0.0f);
  vkernels::kernels::m_grouped_gemm_nt_masked(G, M, N, K, A, B, masked, oracle);

  FBuf da(A.size()), db(B.size()), dc(C.size());
  IBuf dm(G);
  cudaMemcpy(da.ptr, A.data(), A.size() * sizeof(float), cudaMemcpyHostToDevice);
  cudaMemcpy(db.ptr, B.data(), B.size() * sizeof(float), cudaMemcpyHostToDevice);
  cudaMemcpy(dm.ptr, masked.data(), G * sizeof(int), cudaMemcpyHostToDevice);
  vkernels::kernels::cuda::m_grouped_gemm_nt_masked(G, M, N, K, {da.ptr, A.size()},
                                                    {db.ptr, B.size()}, {dm.ptr, G},
                                                    {dc.ptr, C.size()});
  EXPECT_EQ(cudaMemcpy(C.data(), dc.ptr, C.size() * sizeof(float), cudaMemcpyDeviceToHost),
            cudaSuccess);
  expect_same(C, oracle, 1e-3);
}

